// Types and helpers for the root library (data generated by scripts/vocab/gen-roots.py into
// public/data/roots/). Loaded with useStaticData, never bundled.

export const ROOTS_INDEX_PATH = '/data/roots/index.json';
export const rootDataPath = (slug: string) => `/data/roots/${slug}.json`;

/** [slug, Arabic letters, occurrences, number of forms, main meaning, forms that are QuranVocab words] */
export type RootIndexRow = [string, string, number, number, string, number];
export interface RootIndex {
  fields: string[];
  roots: RootIndexRow[];
}

export type FormKind =
  | 'verb'
  | 'noun'
  | 'adjective'
  | 'active participle'
  | 'passive participle'
  | 'verbal noun'
  | 'name'
  | 'time'
  | 'place'
  | 'pronoun'
  | 'demonstrative'
  | 'relative'
  | 'particle'
  | 'other';

export interface RootForm {
  /** The lemma (dictionary form) in Uthmani script. */
  ar: string;
  kind: FormKind;
  /** Verb pattern I-X (as a number) for verbs and verb-derived nouns. */
  form: number | null;
  /** Occurrences in the Quran (word tokens). */
  count: number;
  gloss: string;
  /** QuranVocab word id when this form has its own word page. */
  word: string | null;
  /** Example verse: surah, ayah, word position (1-based), verse words, Saheeh International translation. */
  ex: { s: number; a: number; p: number; ar: string[]; en: string };
}

export interface RootDoc {
  slug: string;
  ar: string;
  total: number;
  /** Core meaning of the root family. */
  core: string;
  forms: RootForm[];
  /** [surah, occurrences], most first. */
  surahs: [number, number][];
}

const ROMAN = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII'];
export const romanForm = (n: number | null) => (n ? ROMAN[n] ?? String(n) : '');

const KIND_LABEL: Record<FormKind, string> = {
  verb: 'Verb',
  noun: 'Noun',
  adjective: 'Adjective',
  'active participle': 'Active participle',
  'passive participle': 'Passive participle',
  'verbal noun': 'Verbal noun',
  name: 'Proper noun',
  time: 'Time word',
  place: 'Place word',
  pronoun: 'Pronoun',
  demonstrative: 'Demonstrative',
  relative: 'Relative pronoun',
  particle: 'Particle',
  other: 'Other',
};

/** "Verb · Form II", "Active participle · Form IV", "Noun". */
export const formLabel = (f: Pick<RootForm, 'kind' | 'form'>) =>
  f.form && (f.kind === 'verb' || f.form > 1) ? `${KIND_LABEL[f.kind]} · Form ${romanForm(f.form)}` : KIND_LABEL[f.kind];

/** Groups shown on a root page, in order. */
export const FORM_GROUPS: { id: string; title: string; kinds: FormKind[] }[] = [
  { id: 'verbs', title: 'Verbs', kinds: ['verb'] },
  {
    id: 'nouns',
    title: 'Nouns and adjectives',
    kinds: ['noun', 'adjective', 'verbal noun', 'active participle', 'passive participle'],
  },
  { id: 'names', title: 'Names', kinds: ['name'] },
  {
    id: 'other',
    title: 'Other words',
    kinds: ['time', 'place', 'pronoun', 'demonstrative', 'relative', 'particle', 'other'],
  },
];
